-- No writes. Run as SQL Editor owner. Runtime checks still require two accounts.
SELECT 'notification RLS' AS check_name,CASE WHEN (SELECT rowsecurity FROM pg_catalog.pg_tables WHERE schemaname='public' AND tablename='notifications') AND EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='public' AND tablename='notifications' AND policyname='dn04_notifications_read') THEN 'PASS' ELSE 'FAIL' END AS result
UNION ALL SELECT 'notification publication',CASE WHEN EXISTS(SELECT 1 FROM pg_catalog.pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='notifications') THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'anonymous RPC denied',CASE WHEN NOT has_function_privilege('anon','public.danest_mark_messages_read_09c2(uuid,uuid[])','EXECUTE') AND NOT has_function_privilege('anon','public.danest_cancel_proposal_09c2(uuid,timestamptz,uuid)','EXECUTE') THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'maintenance server only',CASE WHEN NOT has_function_privilege('authenticated','public.danest_run_maintenance(boolean)','EXECUTE') AND NOT has_function_privilege('authenticated','public.danest_viewing_reminders_09c2(boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.danest_viewing_reminders_09c2(boolean)','EXECUTE') THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'direct notification writes denied',CASE WHEN NOT has_table_privilege('authenticated','public.notifications','UPDATE') AND NOT has_table_privilege('authenticated','public.notifications','INSERT') AND NOT has_table_privilege('authenticated','public.notifications','DELETE') THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'old moderation draft nullable',CASE WHEN EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='moderation_auto' AND column_name='auto_reviewed_at' AND is_nullable='YES') THEN 'PASS' ELSE 'FAIL' END;
-- Check preview without writing. Viewing reminders count recipients, not appointments.
SELECT public.danest_run_maintenance(true) AS maintenance_preview;
